      incorrect: 'Not quite. Python, JavaScript, and Haskell support first-class functions; COBOL does not.',
    },
  },
];

function setsEqual(a, b) {
  if (a.size !== b.size) return false;
  for (const v of a) if (!b.has(v)) return false;
  return true;
}

function buildQuiz() {
  const form = document.getElementById('quiz-form');

  QUESTIONS.forEach((q, index) => {
    const field = document.createElement('div');
    field.className = 'form-field';
    field.dataset.id = q.id;

    const meta = document.createElement('div');
    meta.className = 'question-meta';
    meta.innerHTML = `<span class="question-number">Question ${index + 1} of ${QUESTIONS.length}</span>`;
    field.appendChild(meta);

    const label = document.createElement('p');
    label.className = 'question-label';
    label.textContent = q.text;
    field.appendChild(label);

    if (q.help) {
      const help = document.createElement('p');
      help.className = 'help-text';
      help.textContent = q.help;
      field.appendChild(help);
    }

    const options = document.createElement('div');
    options.className = 'options';

    q.options.forEach(opt => {
      const optLabel = document.createElement('label');
      optLabel.className = 'option';
      optLabel.innerHTML = `
        <input type="checkbox" name="${q.id}" value="${opt.value}" />
        <span class="option-text">${opt.label}</span>
      `;
      options.appendChild(optLabel);
    });

    field.appendChild(options);

    const feedback = document.createElement('p');
    feedback.className = 'field-feedback';
    field.appendChild(feedback);

    form.insertBefore(field, document.getElementById('submit-area'));
  });
}

function handleSubmit(e) {
  e.preventDefault();
  const form = document.getElementById('quiz-form');
  form.classList.add('submitted');

  let score = 0;

  QUESTIONS.forEach(q => {
    const field = form.querySelector(`[data-id="${q.id}"]`);
    const checked = new Set(
      [...field.querySelectorAll('input[type="checkbox"]:checked')].map(cb => cb.value)
    );

    const isCorrect = setsEqual(checked, q.correct);
    if (isCorrect) score++;

    field.classList.add(isCorrect ? 'is-correct' : 'is-incorrect');
    field.querySelector('.field-feedback').textContent = isCorrect
      ? q.feedback.correct
      : q.feedback.incorrect;
  });

  const banner = document.getElementById('score-banner');
  const icon = score === QUESTIONS.length ? '🎉' : score >= 2 ? '👍' : '📚';
  const message = score === QUESTIONS.length
    ? 'Perfect score!'
    : score >= 2
      ? 'Good effort!'
      : 'Keep studying!';

  banner.innerHTML = `
    <span class="score-icon">${icon}</span>
    <div class="score-text">
      <strong>${message}</strong>
      <span>You got ${score} out of ${QUESTIONS.length} questions right.</span>
    </div>
  `;
  banner.classList.add('visible');

  document.getElementById('btn-submit').disabled = true;
  banner.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}

document.addEventListener('DOMContentLoaded', () => {
  buildQuiz();
  document.getElementById('quiz-form').addEventListener('submit', handleSubmit);
});
